#!/usr/bin/env node
/**
 * check-trust-feed-freshness.mjs — S231.
 *
 * Generalizes the S230 `blockDays` trust-ceiling (check-content-freshness.mjs) from
 * curated CONTENT (journal/changelog) to the machine-generated public TRUST feeds that
 * the /status tile and AI agents read: status-proof, uptime, site-health, heartbeat, AI discovery, field wins, geo/staging health, CI status, public status, and security posture.
 *
 * These feeds are regenerated by scheduled workflows (refresh-live-data, uptime-probe)
 * every few hours. When one of those crons silently dies — the S221/S222 dead-cron class,
 * which went undetected for 7+ runs — the feed freezes and the public site keeps serving a
 * stale uptime %/heartbeat that *looks* live. A warn-only signal never stopped that. So each
 * feed declares a hard `blockDays` ceiling: past it, the feed is presumed cron-dead and
 * `build:check` BLOCKS (exit 1), forcing regeneration before the next deploy. Short drifts
 * stay warn-only (a brief CI/weekend gap must never block a routine deploy).
 *
 * Freshness is read from each feed's own `generatedAt` ISO timestamp (observability honesty:
 * the feed self-reports its age). A MISSING/unparseable feed is WARN-only here — existence is
 * already gated by the per-feed generate-*.mjs --check, and treating absent-on-CI as a hard
 * fail would re-introduce the gitignored-input divergence class. This gate is staleness-only.
 *
 * Wired into build:check via check-proof-surface.mjs (NOT a new && segment — the Windows
 * cmd.exe 8191-char build:check chain is at its limit).
 *
 * Usage:
 *   node scripts/check-trust-feed-freshness.mjs              # warn + hard blockDays (build:check)
 *   node scripts/check-trust-feed-freshness.mjs --self-test  # control-proof the classify logic
 */
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

// Each visitor- or agent-facing trust feed: maxDays = warn ceiling, blockDays = hard ceiling.
// Ceilings are generous (days, not hours) so a brief scheduler gap never blocks a deploy,
// while a genuinely dead cron (stale for days) always does.
//
// S238 — publisher provenance (each feed names HOW it is regenerated). When a feed goes
// stale the freshness gate prints the exact `recover` command instead of a vague
// "regenerate api/X.json", and check-feed-publisher-manifest.mjs gates this table for
// parity (every feed declares gen/recover/wf, and every gen script + wf file exists on
// disk — a dead recovery path can never silently rot). gen = canonical generator script;
// recover = exact command to run now; wf = scheduled workflow that keeps it fresh.
export const SURFACES = [
  { name: 'status-proof',      file: 'api/status-proof.json',         tsField: 'generatedAt', maxDays: 2,  blockDays: 4,  gen: 'scripts/build-status-proof.mjs',        recover: 'node scripts/build-status-proof.mjs',          wf: '.github/workflows/uptime-probe.yml' },
  { name: 'uptime',            file: 'api/uptime.json',               tsField: 'generatedAt', maxDays: 2,  blockDays: 4,  gen: 'scripts/probe-uptime.mjs',              recover: 'node scripts/probe-uptime.mjs',                wf: '.github/workflows/uptime-probe.yml' },
  { name: 'site-health',       file: 'api/site-health.json',          tsField: 'generatedAt', maxDays: 2,  blockDays: 4,  gen: 'scripts/build-site-health.mjs',         recover: 'node scripts/build-site-health.mjs',           wf: '.github/workflows/pages-deploy.yml' },
  { name: 'heartbeat',         file: 'api/heartbeat.json',            tsField: 'generatedAt', maxDays: 2,  blockDays: 4,  gen: 'scripts/generate-heartbeat.mjs',        recover: 'node scripts/generate-heartbeat.mjs',          wf: '.github/workflows/pages-deploy.yml' },
  { name: 'ai-discovery',      file: 'api/ai-discovery-health.json',  tsField: 'generatedAt', maxDays: 2,  blockDays: 4,  gen: 'scripts/build-ai-discovery-health.mjs', recover: 'node scripts/build-ai-discovery-health.mjs',   wf: '.github/workflows/pages-deploy.yml' },
  { name: 'field-win',         file: 'api/field-win.json',            tsField: 'generatedAt', maxDays: 2,  blockDays: 4,  gen: 'scripts/build-field-win-proof.mjs',     recover: 'node scripts/build-field-win-proof.mjs',       wf: '.github/workflows/pages-deploy.yml' },
  { name: 'geo-vitals',        file: 'api/geo-vitals.json',           tsField: 'generatedAt', maxDays: 2,  blockDays: 4,  gen: 'scripts/build-geo-vitals.mjs',          recover: 'node scripts/build-geo-vitals.mjs',            wf: '.github/workflows/uptime-probe.yml' },
  { name: 'staging-health',    file: 'api/staging-health.json',       tsField: 'generatedAt', maxDays: 7,  blockDays: 10, gen: 'scripts/check-staging-parity.mjs',      recover: 'node scripts/check-staging-parity.mjs --refresh', wf: '.github/workflows/uptime-probe.yml' },
  { name: 'ci-status',         file: 'api/ci-status.json',            tsField: 'generatedAt', maxDays: 4,  blockDays: 7,  gen: 'scripts/build-nervous-system.mjs',      recover: 'node scripts/build-nervous-system.mjs',        wf: '.github/workflows/pages-deploy.yml' },
  { name: 'public-status',     file: 'api/public-status.json',        tsField: 'generatedAt', maxDays: 30, blockDays: 45, gen: 'scripts/build-public-status.mjs',       recover: 'node scripts/build-public-status.mjs',         wf: '.github/workflows/pages-deploy.yml' },
  { name: 'security-posture',  file: 'api/security-posture.json',     tsField: 'generatedAt', maxDays: 30, blockDays: 45, gen: 'scripts/build-security-posture.mjs',    recover: 'node scripts/build-security-posture.mjs',      wf: '.github/workflows/pages-deploy.yml' },
  { name: 'og-coverage',       file: 'api/og-coverage.json',          tsField: 'generatedAt', maxDays: 2,  blockDays: 4,  gen: 'scripts/build-og-coverage.mjs',         recover: 'node scripts/build-og-coverage.mjs',           wf: '.github/workflows/pages-deploy.yml' },
  // S329: /ignis/roi/ shipped a 3-month-stale feed with no freshness ceiling —
  // a linked public intelligence surface silently rotting. Now in the build
  // chain (refresh-live-data regenerates it 6x/day) with a ceiling.
  { name: 'ignis-roi',         file: 'api/ignis-roi.json',            tsField: 'generatedAt', maxDays: 7,  blockDays: 21, gen: 'scripts/build-ignis-roi.mjs',           recover: 'node scripts/build-ignis-roi.mjs',             wf: '.github/workflows/refresh-live-data.yml' },
];

/**
 * Pure verdict. `blocked` is true only when the surface declares a blockDays ceiling
 * AND the feed's age exceeds it. Mirrors check-content-freshness.classify().
 */
export function classify(generatedAt, nowMs, maxDays, blockDays = null) {
  if (!generatedAt) return { status: 'unknown', ageDays: null, blocked: false };
  const t = Date.parse(generatedAt);
  if (Number.isNaN(t)) return { status: 'unknown', ageDays: null, blocked: false };
  const ageDays = (nowMs - t) / 86_400_000;
  const blocked = blockDays != null && ageDays > blockDays;
  return { status: ageDays > maxDays ? 'stale' : 'fresh', ageDays: Math.round(ageDays * 10) / 10, blocked };
}

function readGeneratedAt(file, tsField) {
  const abs = join(ROOT, file);
  if (!existsSync(abs)) return { missing: true, value: null };
  try {
    const json = JSON.parse(readFileSync(abs, 'utf8'));
    return { missing: false, value: json[tsField] ?? null };
  } catch {
    return { missing: false, value: null, parseError: true };
  }
}

function evaluate(nowMs = Date.now()) {
  const results = [];
  for (const s of SURFACES) {
    const { missing, value } = readGeneratedAt(s.file, s.tsField);
    results.push({ ...s, missing, ...classify(value, nowMs, s.maxDays, s.blockDays) });
  }
  return results;
}

function selfTest() {
  const now = Date.parse('2026-06-27T12:00:00Z');
  let pass = 0, fail = 0;
  const check = (label, cond) => { if (cond) { pass++; } else { fail++; console.error('  ✗ ' + label); } };
  const ago = (days) => new Date(now - days * 86_400_000).toISOString();

  check('fresh within maxDays → not stale, not blocked', (() => {
    const r = classify(ago(1), now, 2, 4); return r.status === 'fresh' && r.blocked === false;
  })());
  check('past maxDays but within blockDays → stale, not blocked', (() => {
    const r = classify(ago(3), now, 2, 4); return r.status === 'stale' && r.blocked === false;
  })());
  check('past blockDays → stale AND blocked', (() => {
    const r = classify(ago(5), now, 2, 4); return r.status === 'stale' && r.blocked === true;
  })());
  check('no blockDays declared → never blocked even when ancient', (() => {
    const r = classify(ago(900), now, 2, null); return r.blocked === false;
  })());
  check('missing/empty timestamp → unknown, not blocked', (() => {
    const r = classify(null, now, 2, 4); return r.status === 'unknown' && r.blocked === false;
  })());
  check('unparseable timestamp → unknown, not blocked', (() => {
    const r = classify('not-a-date', now, 2, 4); return r.status === 'unknown' && r.blocked === false;
  })());

  console.log(`check-trust-feed-freshness self-test: ${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
}

const isMain = process.argv[1] &&
  process.argv[1].replace(/\\/g, '/').endsWith('scripts/check-trust-feed-freshness.mjs');

if (isMain) {
  if (process.argv.includes('--self-test')) selfTest();

  const results = evaluate();
  let blocked = 0, warned = 0;
  for (const r of results) {
    const icon = r.blocked ? '⛔' : r.missing ? '∅' : r.status === 'stale' ? '⚠' : r.status === 'fresh' ? '✓' : '∅';
    const age = r.ageDays == null ? (r.missing ? 'missing' : 'no-timestamp') : `${r.ageDays}d`;
    const note = r.blocked
      ? ` — BLOCKED (>${r.blockDays}d ceiling; presumed cron-dead, recover: ${r.recover})`
      : r.status === 'stale' ? ` — stale (>${r.maxDays}d warn · recover: ${r.recover})` : '';
    console.log(`  ${icon}  ${r.name.padEnd(13)} ${age}${note}`);
    if (r.blocked) blocked++;
    else if (r.status === 'stale' || r.missing) warned++;
  }
  if (blocked) {
    console.error(`check-trust-feed-freshness: ${blocked} trust feed(s) past their hard blockDays ceiling — a dead generator is serving a stale public trust signal.`);
    process.exit(1);
  }
  console.log(`check-trust-feed-freshness ✓ ${results.length} trust feed(s) within freshness ceilings${warned ? ` (${warned} warn)` : ''}`);
}
